"use strict";
// Price check — the team guide (page generated by price-check/tools/guide_html.py from the guide's Markdown, French
// and English). Romain, 2026-10-03: « quelqu'un qui a accès à l'admin a accès à ce guide ». This script only switches
// the language (remembered, or chosen by #fr / #en in the address) and the theme; the page carries the text itself.
(function () {
  const $ = (s) => document.querySelector(s);
  const store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode: the choice is not kept */ } },
  };
  const saved = store.get("aks-theme");
  if (saved) document.documentElement.setAttribute("data-theme", saved);
  $("#theme").addEventListener("click", () => {
    const cur = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", cur);
    store.set("aks-theme", cur);
  });
  function show(lang) {
    for (const l of ["fr", "en"]) {
      $("#guide-" + l).classList.toggle("hidden", l !== lang);
      $("#lang-" + l).setAttribute("aria-pressed", String(l === lang));
    }
    document.documentElement.setAttribute("lang", lang);
    store.set("pc-guide-lang", lang);
  }
  $("#lang-fr").addEventListener("click", () => show("fr"));
  $("#lang-en").addEventListener("click", () => show("en"));
  const hash = (typeof location !== "undefined" && location.hash) || "";
  // English by default since 07/10/2026 (« tout l'outil en anglais »)
  const asked = hash.startsWith("#en") ? "en" : hash.startsWith("#fr") ? "fr" : store.get("pc-guide-lang") || store.get("aks-lang");
  show(asked === "fr" ? "fr" : "en");
})();
